/* Convert API v3 Response To Dynamic System Prompt */

const responseData = $input.first().json;
const data         = responseData.Data;

if (!data || !data.FormFields) {
	throw new Error('Response data invalid or empty');
}

/* Create Slug Function: "First Name" → "First_Name", keep punctuation */
const toSlug = (name) => {
	return name
		.trim()
		.replace(/\s+/g, '_'); // Replace spaces with underscores
};

/* Create Field Mapping: slug -> field data */
const fieldMapping = {};
data.FormFields.forEach(f => {
	const slug = toSlug(f.Name);
	fieldMapping[slug] = {
		id          : f.Id,
		name        : f.Name,
		type        : f.Type,
		required    : f.Required,
		placeholder : f.Placeholder,
		options     : f.Options || []
	};
});

/* Find Email And Phone Fields */
const emailField = data.FormFields.find(f => f.Type === 'email');
const phoneField = data.FormFields.find(f => f.Type === 'usphonenumber');

/* Separate Required And Optional Fields */
const requiredFields = data.FormFields.filter(f => f.Required);
const optionalFields = data.FormFields.filter(f => !f.Required);

/* Build Required Fields List */
const requiredList = requiredFields.map(f => {
	const placeholder = f.Placeholder && f.Placeholder !== '' ? ` - Example: ${f.Placeholder}` : '';
	const options     = f.Options && f.Options.length > 0 
		? ` - Options: ${f.Options.map(o => `${o.Id}: ${o.Name}`).join(', ')}`
		: '';
	return `- ${f.Name}${placeholder}${options}`;
}).join('\n');

/* Build Optional Fields List */
const optionalList = optionalFields.length > 0 
	? '\n\nOptional fields:\n' + optionalFields.map(f => {
		const placeholder = f.Placeholder && f.Placeholder !== '' ? ` - Example: ${f.Placeholder}` : '';
		const options     = f.Options && f.Options.length > 0 
			? ` - Options: ${f.Options.map(o => `${o.Id}: ${o.Name}`).join(', ')}`
			: '';
		return `- ${f.Name}${placeholder}${options}`;
	}).join('\n')
	: '';

/* Build JSON Example */
const jsonExample = {};
data.FormFields.forEach(f => {
	const slug = toSlug(f.Name);
	if (f.Type === 'list' && f.Options.length > 0) {
		jsonExample[slug] = String(f.Options[0].Id);
	} else if (f.Type === 'email') {
		jsonExample[slug] = 'user@example.com';
	} else if (f.Type === 'usphonenumber') {
		jsonExample[slug] = '1234567890';
	} else if (f.Type === 'birthdate') {
		jsonExample[slug] = 'MM/DD/YYYY';
	} else if (f.Type === 'number') {
		jsonExample[slug] = '0';
	} else {
		jsonExample[slug] = '<value>';
	}
});

/* Dynamic System Prompt */
const systemPrompt = `You are a friendly assistant helping users register for a sweepstake.

When you have ALL the required data from the user, respond ONLY with a JSON object containing the user's information.

Required fields:
${requiredList}${optionalList}

When you have ALL the required data, respond with this EXACT JSON format (use the exact field names with underscores):

{
  "action": "create_participant",
${Object.entries(jsonExample).map(([key, val]) => `  "${key}": "${val}"`).join(',\n')}
}

Important:
- Ask for ONE field at a time in a conversational way
- Be friendly and engaging
- Validate data formats before proceeding
- When you have ALL the required data, respond ONLY with the JSON (no additional text)
- Use EXACTLY the field names shown above (with underscores replacing spaces)
- For list/select fields, use the option ID number, not the name
- DO NOT use placeholder text, use actual user data
- DO NOT include any other fields in the JSON`;

/* Return System Prompt And Data */
return {
	json: {
		systemPrompt       : systemPrompt,
		fieldMapping       : fieldMapping,
		emailFieldSlug     : emailField ? toSlug(emailField.Name) : 'Email',
		phoneFieldSlug     : phoneField ? toSlug(phoneField.Name) : 'Mobile_Number',
		sweepstakesToken   : data.SweepstakesToken,
		entryPageToken     : data.EntryPageToken,
		chatInput          : $('When chat message received').item.json.chatInput,
		sessionId          : $('When chat message received').item.json.sessionId
	}
};

