/* Extract AI Response And Prompt Data */
const aiOutput   = $input.first().json.output;
const promptData = $('Build Dynamic Prompt').first().json;

/* Clean Markdown */
const cleanOutput = aiOutput.replace(/```json\s*/g, '').replace(/```/g, '').trim();

/* Parse JSON */
const parsed = JSON.parse(cleanOutput);

/* Check Action */
if (parsed.action !== 'create_participant') {
	return { json: {} };
}

/* Remove Action */
const { action, ...fields } = parsed;

/* Extract Email And Phone Values */
const keyEmail       = fields[promptData.emailFieldSlug] || '';
const keyPhoneNumber = fields[promptData.phoneFieldSlug] || '';

/* Debug Output */
const result = {
	KeyEmail       : keyEmail,
	KeyPhoneNumber : keyPhoneNumber,
	BonusEntries   : 0,
	Fields         : fields
};

console.log('=== TRANSFORM OUTPUT ===');
console.log(JSON.stringify(result, null, 2));

/* Return Format For Sweeppea Node */
return {
	json: result
};
